    { map = "CF_MaraudonA", label = "Maraudos (4th Khan)", x = 264, y = 236, note = "Only for The Pariah's Instructions: a Khan ghost in the purple wing (The Wicked Grotto), between the purple entrance and Vyletongue (spot 4 on the map). Seen in our run 11-19: killed in the Grotto before Vyletongue Seat. Not in our spawn data, so no line.", opt = true, npc = 13739 },
    { map = "CF_MaraudonA", label = "Lord Vyletongue", x = 199, y = 288, note = "Through The Wicked Grotto into Vyletongue Seat. Drops the Celebrian Diamond (Legends of Maraudon). Four hidden guards stand with him: the front two can be pulled without him.", npc = 12236, line = {404,279,374,274,347,260,334,243,315,235,303,217,294,209,281,208,268,214,258,212,254,199,222,207,200,177,204,171,204,163,211,156,206,147,187,153,178,162,176,177,173,179,131,169,117,171,113,189,117,200,140,191,157,198,179,197,189,200,209,214,213,221,218,242,197,248,191,254,197,267,199,288} },
    { map = "CF_MaraudonA", label = "Razorlash", x = 85, y = 161, note = "Back through the Grotto and Poison Falls into Foulspore Cavern (the orange wing). Can be skipped. His bleed stacks: the tank uses a cooldown at high stacks. Kill the black Barbed Lashers in this wing first: their stun hits the whole group.", opt = true, npc = 12258, line = {199,288,197,273,191,254,197,248,211,251,218,242,213,221,209,214,189,200,179,197,157,198,140,191,117,200,113,189,114,171,111,163,109,161,85,161} },
    { map = "CF_MaraudonA", label = "Noxxion", x = 188, y = 86, note = "Drops the Celebrian Rod (Legends of Maraudon). Click the Larva Spewer near him to stop more larvae. This wing has the Vylestem vines: small purple-topped plants; use the filled vial on one, 2-3 Scions come out (immune to Nature), each kill counts.", npc = 13282, line = {199,288,197,273,191,254,197,248,211,251,218,242,213,221,209,214,189,200,179,197,157,198,140,191,117,200,113,189,117,171,131,169,157,176,178,162,187,153,194,140,192,126,199,120,188,86} },
