    { map = "CF_MaraudonA", label = "Celebras the Cursed", x = 47, y = 309, note = "Poison Falls: hug the walls or stay in the water to skip most mobs (the slow Creeping Sludges hit hard). Have the Rod AND the Diamond before he dies. Interrupt his casts.", warn = "Celebras the Redeemed appears after he dies. Everyone on Legends of Maraudon turns it in at him (the ?) first. Then ONE player starts the ritual (\"I carry both parts of the scepter\"): EVERYONE who needs the Scepter follows him to the altar and reads his book, one at a time. The book is only there about a minute. He can vanish when the first ritual ends (our group, 2026-11-19: he left after one player's Scepter and 4 couldn't do it): all of you at the altar, ready, before anyone starts. Don't jump into the water before this is done. He comes only once per run: when he leaves, Legends of Maraudon waits for a fresh instance (bosses stay dead after the trash respawns).", npc = 12225, line = {188,86,199,120,192,126,194,140,178,162,176,177,173,179,131,169,117,171,113,189,117,200,114,208,93,229,88,230,44,262,47,309} },
    { map = "CF_MaraudonB", label = "Landslide", x = 301, y = 197, note = "Jump off the ledge over the waterfall past Celebras (there may be no way back up: unconfirmed). Let the two elemental patrols pass. Tank him with your back to a wall; his small adds are weak and vanish when he dies.", npc = 12203 },
    { map = "CF_MaraudonB", label = "Tinkerer Gizlock", x = 390, y = 305, note = "Just off the ramp down from Landslide, on the way to the Princess. Face him away from the group and stand in melee: his Flash Bomb fears bears and pets.", opt = true, npc = 13601, line = {301,197,309,210,306,225,283,231,267,241,265,270,279,283,311,288,321,302,344,303,371,296,372,288,382,283,391,299,390,305} },
